insert into public.drill_blocks (pathway, level_min, level_max, youth_stage, quarter, block_order, title, content) values
  ('youth', null, null, 'red_starter', 1, 2, 'Red Starter', '{"name": "Red Starter", "blurb": "Ball tracking, balance, catching, and first taps with the racquet — no rallying pressure yet, just games.", "badges": ["Bounce & Catch", "Ready-Position Freeze Game", "Balloon Volley Rally", "Rolling-Ball Scoop Pickup", "Underhand Toss to a Target", "Racquet Balance Walk"], "forehand": "Light self-bounce forehand taps from a stationary stance — ball drops from the coach''s hand right in front, no real swing yet, just ''meet the ball in front'' repetition.", "backhand": "Two-hand hammer-grip taps off a very close, slow stationary feed — same ''meet it in front'' cue as the forehand, building the turn-and-tap pattern on both sides.", "volley": "Frying-pan-grip catch-and-tap games closer to the net, adding a gentle push-forward motion instead of just holding the racquet still.", "serve": "Underhand toss practice into a big, close target (a hoop or cone) — still no real swing, focus stays entirely on a clean, straight toss.", "footwork": "Balance-beam-style line walks plus a ''scarf scoop'' catching game that adds gentle directional movement to the freeze-position work.", "game": "Parachute or scarf catch-and-throw relays mixed with racquet taps — keeps engagement high while grooving the same contact patterns."}'::jsonb),
  ('youth', null, null, 'red_starter', 1, 3, 'Red Starter', '{"name": "Red Starter", "blurb": "Ball tracking, balance, catching, and first taps with the racquet — no rallying pressure yet, just games.", "badges": ["Bounce & Catch", "Ready-Position Freeze Game", "Balloon Volley Rally", "Rolling-Ball Scoop Pickup", "Underhand Toss to a Target", "Racquet Balance Walk"], "forehand": "First tiny full swings off a very slow, close underhand feed — small backswing, contact out in front, no target pressure, just completing a real forehand motion for the first time.", "backhand": "Same first-tiny-swing idea on the two-handed side, matched rep-for-rep with the forehand so neither wing gets left behind.", "volley": "Short cooperative tap-rallies over a rope or low net line — two taps, then three, building toward a real net exchange.", "serve": "Toss-and-tap into the box from a step closer than usual, adding the very beginning of a downward tap motion after the toss.", "footwork": "Freeze-on-whistle games played while already moving (not just standing still), plus a repeat of the animal-walk patterns at faster speed.", "game": "Mini badge-check days — coach quietly notes who''s ready for which Red Starter badge while running the same fun games as always."}'::jsonb),
  ('youth', null, null, 'red_starter', 1, 4, 'Red Starter', '{"name": "Red Starter", "blurb": "Ball tracking, balance, catching, and first taps with the racquet — no rallying pressure yet, just games.", "badges": ["Bounce & Catch", "Ready-Position Freeze Game", "Balloon Volley Rally", "Rolling-Ball Scoop Pickup", "Underhand Toss to a Target", "Racquet Balance Walk"], "forehand": "Graduation-readiness check: 2-3 self-bounce-and-hit attempts in a row, still no pressure to keep score, just seeing the swing hold together for multiple reps.", "backhand": "Same graduation-readiness check on the two-handed side — 2-3 self-bounce-and-hit attempts, matched to the forehand.", "volley": "A short cooperative ''keep it going'' rally at the net — first taste of a real back-and-forth exchange before moving to Red Rally.", "serve": "Toss-and-tap combined into one smoother motion for the first time, aimed at the same close target used all stage.", "footwork": "Full obstacle-course review of every footwork game played this stage, run as one fun combined circuit.", "game": "Celebration mini-games plus badge ceremony for anything earned this stage — and a first look at the bigger mini-court waiting in Red Rally."}'::jsonb),
  ('youth', null, null, 'red_rally', 2, 2, 'Red Rally', '{"name": "Red Rally", "blurb": "First real racquet-and-ball rallying on the mini (36-ft) red-ball court, plus first serves.", "badges": ["Self-Bounce Rally (3 hits)", "Forehand Contact Point", "Backhand Contact Point", "Sideways Shuffle Steps", "Mini-Court Feed Rally (5 balls)", "Drop-and-Hit Serve"], "forehand": "Self-drop forehand rally reps extended to 5-7 in a row, now aimed at a left or right target cone instead of just anywhere in the court.", "backhand": "Two-handed backhand off a coach feed, same left/right cone targeting as the forehand, keeping both wings at matching rep counts.", "volley": "Volley points started from a short feed just inside the service line, now with a simple target zone to punch the ball into.", "serve": "Drop-and-hit serve aimed at a specific quadrant of the box (not just ''anywhere in''), alternating deuce and ad side each turn.", "footwork": "Ladder-style quick-step patterns added to the sideways shuffle work, building foot speed before the ball is fed.", "game": "Mini-court rally games extended to keep-it-in-7 as a team target, plus first simple point games worth one point each."}'::jsonb),
  ('youth', null, null, 'red_rally', 2, 3, 'Red Rally', '{"name": "Red Rally", "blurb": "First real racquet-and-ball rallying on the mini (36-ft) red-ball court, plus first serves.", "badges": ["Self-Bounce Rally (3 hits)", "Forehand Contact Point", "Backhand Contact Point", "Sideways Shuffle Steps", "Mini-Court Feed Rally (5 balls)", "Drop-and-Hit Serve"], "forehand": "Forehand rally patterns alternating with the backhand on the same feed — first look at ''which wing do I use'' decision-making mid-rally.", "backhand": "Same alternating-wing pattern from the backhand side, plus a first look at stepping in to attack a short, slow feed.", "volley": "Volley points that start with a short ball approach — move in, then volley — instead of starting already positioned at the net.", "serve": "Serve consistency streaks: 3 in a row inside the box before rotating server, building toward real first-serve reliability.", "footwork": "Split-step timing introduced on a feed cue for the first time, layered on top of the shuffle-step foundation.", "game": "First-to-5 scoring mini-matches on the mini court, with players calling their own line for the first time."}'::jsonb),
  ('youth', null, null, 'red_rally', 2, 4, 'Red Rally', '{"name": "Red Rally", "blurb": "First real racquet-and-ball rallying on the mini (36-ft) red-ball court, plus first serves.", "badges": ["Self-Bounce Rally (3 hits)", "Forehand Contact Point", "Backhand Contact Point", "Sideways Shuffle Steps", "Mini-Court Feed Rally (5 balls)", "Drop-and-Hit Serve"], "forehand": "Full stage review under the ''Red Rally Cup'' format — forehand rally reps applied directly inside real games rather than as standalone drilling.", "backhand": "Same Red Rally Cup review for the backhand side, making sure both wings hold up once real scoring is on the line.", "volley": "Volley points used as a real tactical choice during Cup matches — closing in behind a good approach shot instead of only on command.", "serve": "Serve rotation through a full Cup format, serving from both the deuce and ad side under real match pressure.", "footwork": "All of this stage''s footwork patterns (shuffle, ladder, split-step) combined and tested live during Cup matches.", "game": "Red Rally Cup mini-tournament — full games, real scoring, celebration for everyone, and a first look at the full 60-ft court waiting in Red Game Player."}'::jsonb),
  ('youth', null, null, 'red_game_player', 3, 2, 'Red Game Player', '{"name": "Red Game Player", "blurb": "Real mini-tennis scoring, court positioning, and the first lessons in sportsmanship.", "badges": ["Count-to-7 Scoring", "Two-Bounce Rule Understanding", "Court Position Awareness", "Doubles Teamwork Game", "Good-Sport Handshake", "Call-Your-Own-Line Honesty"], "forehand": "Cross-court forehand consistency targets — a cone or line marking the cross-court lane, rewarding direction as much as clean contact.", "backhand": "Matching cross-court backhand target work, plus continued reps on the one-handed slice block introduced last stage.", "volley": "Approach-shot-into-volley sequences: hit an approach, move in, finish the point at net — the first two-shot pattern of the pathway.", "serve": "Serve placement practice aiming for the deuce and ad corners specifically, not just landing anywhere inside the box.", "footwork": "Recovery-step games under repeated pressure — multiple balls in a row instead of one-and-done — building real court-coverage stamina.", "game": "Doubles positioning reps (up-and-back formation) layered onto the scoring mini-matches from last stage."}'::jsonb),
  ('youth', null, null, 'red_game_player', 3, 3, 'Red Game Player', '{"name": "Red Game Player", "blurb": "Real mini-tennis scoring, court positioning, and the first lessons in sportsmanship.", "badges": ["Count-to-7 Scoring", "Two-Bounce Rule Understanding", "Court Position Awareness", "Doubles Teamwork Game", "Good-Sport Handshake", "Call-Your-Own-Line Honesty"], "forehand": "Point-construction forehand work: recognizing a short ball and moving forward to attack it, rather than always rallying from the baseline.", "backhand": "Same short-ball recognition and attack pattern from the backhand side, keeping both wings equally comfortable moving forward.", "volley": "Serve-and-first-volley pattern for net-rushers, plus continued approach-and-finish sequences from a rally.", "serve": "Serve-plus-first-shot pattern: serve to a target, then immediately execute a planned follow-up shot.", "footwork": "Simple tactical footwork rules introduced — recover to the middle after a cross-court shot, cover the line after a down-the-line shot.", "game": "Real scoring sets applying today''s short-ball and serve-plus-one patterns, not just point-by-point mini-games."}'::jsonb),
  ('youth', null, null, 'red_game_player', 3, 4, 'Red Game Player', '{"name": "Red Game Player", "blurb": "Real mini-tennis scoring, court positioning, and the first lessons in sportsmanship.", "badges": ["Count-to-7 Scoring", "Two-Bounce Rule Understanding", "Court Position Awareness", "Doubles Teamwork Game", "Good-Sport Handshake", "Call-Your-Own-Line Honesty"], "forehand": "Full ''Red Court Championship'' review — forehand consistency and point-construction patterns tested directly in tournament-format matches.", "backhand": "Same Championship-format review for the backhand, confirming the slice block and cross-court targets hold up under real pressure.", "volley": "Net play used as a real tactical weapon during Championship matches — approaching and volleying by choice, not on command.", "serve": "Full serve rotation (deuce/ad, placement, serve-plus-one) tested live across Championship-format matches.", "footwork": "Every footwork pattern from this stage (recovery, cross-court/line rules) combined and pressure-tested in real matches.", "game": "Red Court Championship — full matches, doubles included, serve rotation, sportsmanship and line-calling review, and a first look at the bigger orange court waiting next."}'::jsonb),
  ('youth', null, null, 'orange_ready', 4, 2, 'Orange Ready', '{"name": "Orange Ready", "blurb": "Stretching rallies longer, first shot-selection ideas, and getting comfortable on the bigger orange-ball court.", "badges": ["Sustained Rally (5+ both sides)", "Move-Up on a Short Ball", "Stay-Back on a Deep Ball", "Play a Mini-Tournament", "Orange-Ball Comfort Rally", "Serve Into the Box (3 in a row)"], "forehand": "Forehand rally tolerance stretched to 8-10+ balls with a directional target added, combining the topspin shape from last quarter with real consistency demands.", "backhand": "Same extended rally-tolerance work on the backhand, alternating topspin depth reps with slice reps for a fast or low ball.", "volley": "Approach-shot-into-volley sequences on the full orange court, finishing with a real directional punch instead of just contact.", "serve": "Serve-plus-first-shot pattern introduced on the orange court — serve to a target, then execute one planned follow-up shot.", "footwork": "Agility and lateral movement drilled against a live (not fed) ball for the first time, raising the reaction-speed bar.", "game": "Extended-rally mini-games plus first simple doubles positioning on the full-size orange court."}'::jsonb),
